22%20stroke-linejoin%3D%22round%22%2F%3E%3Cpath%20d%3D%22M134%20112%20L170%20100%20L200%20122%20L230%20100%20L266%20112%20L336%20164%20L308%20220%20L276%20192%20L276%20412%20L124%20412%20L124%20192%20L92%20220%20L64%20164%20Z%22%20fill%3D%22url(%23f14)%22%2F%3E%3Cpath%20d%3D%22M170%20100%20L200%20148%20L230%20100%20L246%20116%20L200%20164%20L154%20116%20Z%22%20fill%3D%22%23a07c54%22%20stroke%3D%22%23695038%22%20stroke-width%3D%222%22%20stroke-linejoin%3D%22round%22%2F%3E%3Cpath%20d%3D%22M200%20164%20V412%22%20fill%3D%22none%22%20stroke%3D%22%23695038%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%20opacity%3D%22.8%22%2F%3E%3Ccircle%20cx%3D%22200%22%20cy%3D%22192%22%20r%3D%224.5%22%20fill%3D%22%23cfb699%22%20stroke%3D%22%23634a35%22%20stroke-width%3D%221.5%22%2F%3E%3Ccircle%20cx%3D%22200%22%20cy%3D%22238%22%20r%3D%224.5%22%20fill%3D%22%23cfb699%22%20stroke%3D%22%23634a35%22%20stroke-width%3D%221.5%22%2F%3E%3Ccircle%20cx%3D%22200%22%20cy%3D%22284%22%20r%3D%224.5%22%20fill%3D%22%23cfb699%22%20stroke%3D%22%23634a35%22%20stroke-width%3D%221.5%22%2F%3E%3Ccircle%20cx%3D%22200%22%20cy%3D%22330%22%20r%3D%224.5%22%20fill%3D%22%23cfb699%22%20stroke%3D%22%23634a35%22%20stroke-width%3D%221.5%22%2F%3E%3Ccircle%20cx%3D%22200%22%20cy%3D%22376%22%20r%3D%224.5%22%20fill%3D%22%23cfb699%22%20stroke%3D%22%23634a35%22%20stroke-width%3D%221.5%22%2F%3E%3Cpath%20d%3D%22M138%20214%20H176%20V252%20H138%20Z%22%20fill%3D%22none%22%20stroke%3D%22%23695038%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%20stroke-dasharray%3D%224%204%22%20opacity%3D%22.8%22%2F%3E%3Cpath%20d%3D%22M128%20398%20H272%22%20fill%3D%22none%22%20stroke%3D%22%23695038%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%20stroke-dasharray%3D%224%204%22%20opacity%3D%22.8%22%2F%3E%3C%2Fg%3E%3C%2Fsvg%3E', '[{"type":"p","text":"Before you look at the price, turn the garment inside out. The label is the most honest record a piece carries, and most of what it says is easy to read once you know where to look."},{"type":"h2","text":"Start with the fibre line"},{"type":"p","text":"Sewn-in care instructions became standard through the 1970s and 80s, so a piece with none at all is often older, or was made by a very small maker. A short fibre line and nothing else is a good sign. A long list of washing symbols usually points to something newer."},{"type":"p","text":"Fibre names are worth reading too. Blends of acetate, rayon and nylon turn up often in older dresses and blouses, while heavy pure wool and cotton drill are common in workwear and tailoring."},{"type":"h2","text":"Look at how the label is attached"},{"type":"p","text":"A woven label stitched down on all four sides tends to be older than a printed one or a tag held at the top edge only. The sizing system and the country of origin add more clues, but treat each one as a hint rather than proof."},{"type":"quote","text":"A label gives you a range, not a date. Two clues that agree are worth more than one that sounds certain."},{"type":"h2","text":"Check the zip and the stitching"},{"type":"p","text":"Metal zips with a maker’s name on the pull are common on older pieces, and plastic coil zips arrive later in most categories. Even stitching and finished seams on the inside suggest a garment made to last, which is also what our curators look for."},{"type":"p","text":"Every piece on RE:WEAR is photographed with its label wherever it has one. It is the second photo you see when you hover over a product."}]'::jsonb, '2026-09-28'::date),
  ('0d292689-5b9b-5de8-8f25-15a07e06dca4'::uuid, 'the-nineties-denim-jacket', 'The 90s denim jacket, one more time', 'Story', 'Raka Pratama', 'Boxy, faded and a little too big. Why the chore jacket keeps coming back, and how to tell a good one from a tired one.', 'data:image/svg+xml;utf8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20800%20600%22%20width%3D%22800%22%20height%3D%22600%22%3E%3Crect%20width%3D%22800%22%20height%3D%22600%22%20fill%3D%22%23E8D8CF%22%2F%3E%3Cpath%20d%3D%22M30%20100%20H770%22%20stroke%3D%22%232D1F1A%22%20stroke-width%3D%223%22%20stroke-linecap%3D%22round%22%2F%3E%3Cpath%20d%3D%22M190%20100%20V160%22%20stroke%3D%22%232D1F1A%22%20stroke-width%3D%222%22%2F%3E%3Cg%20transform%3D%22translate(18%2074)%20scale(0.86)%22%3E%3Cpath%20d%3D%22M130%20118%20L168%20104%20L200%20128%20L232%20104%20L270%20118%20L338%20186%20L346%20336%20L304%20342%20L296%20236%20L292%20402%20L108%20402%20L104%20236%20L96%20342%20L54%20336%20L62%20186%20Z%22%20fill%3D%22%237F94A6%22%20stroke%3D%22%23525459%22%20stroke-width%3D%222%22%20stroke-linejoin%3D%22round%22%2F%3E%3Cpath%20d%3D%22M168%20104%20L200%20128%20L232%20104%20L246%20120%20L200%20160%20L154%20120%20Z%22%20fill%3D%22%23748492%22%20stroke%3D%22%23525459%22%20stroke-width%3D%222%22%20stroke-linejoin%3D%22round%22%2F%3E%3Cpath%20d%3D%22M200%20160%20V402%22%20fill%3D%22none%22%20stroke%3D%22%23525459%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%20opacity%3D%22.8%22%2F%3E%3Cpath%20d%3D%22M138%20214%20H182%20V260%20H138%20Z%22%20fill%3D%22none%22%20stroke%3D%22%23525459%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%20stroke-dasharray%3D%224%204%22%20opacity%3D%22.8%22%2F%3E%3Cpath%20d%3D%22M218%20214%20H262%20V260%20H218%20Z%22%20fill%3D%22none%22%20stroke%3D%22%23525459%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%20stroke-dasharray%3D%224