%22%20stroke%3D%22%23493a33%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%20opacity%3D%22.8%22%2F%3E%3Cpath%20d%3D%22M165.2%20136%20L126.8%20440%22%20fill%3D%22none%22%20stroke%3D%22%23493a33%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%20opacity%3D%22.8%22%2F%3E%3Cpath%20d%3D%22M176.8%20136%20L151.2%20440%22%20fill%3D%22none%22%20stroke%3D%22%23493a33%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%20opacity%3D%22.8%22%2F%3E%3Cpath%20d%3D%22M188.4%20136%20L175.6%20440%22%20fill%3D%22none%22%20stroke%3D%22%23493a33%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%20opacity%3D%22.8%22%2F%3E%3Cpath%20d%3D%22M200%20136%20L200%20440%22%20fill%3D%22none%22%20stroke%3D%22%23493a33%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%20opacity%3D%22.8%22%2F%3E%3Cpath%20d%3D%22M211.6%20136%20L224.39999999999998%20440%22%20fill%3D%22none%22%20stroke%3D%22%23493a33%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%20opacity%3D%22.8%22%2F%3E%3Cpath%20d%3D%22M223.2%20136%20L248.79999999999998%20440%22%20fill%3D%22none%22%20stroke%3D%22%23493a33%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%20opacity%3D%22.8%22%2F%3E%3Cpath%20d%3D%22M234.8%20136%20L273.2%20440%22%20fill%3D%22none%22%20stroke%3D%22%23493a33%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%20opacity%3D%22.8%22%2F%3E%3Cpath%20d%3D%22M246.39999999999998%20136%20L297.6%20440%22%20fill%3D%22none%22%20stroke%3D%22%23493a33%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%20opacity%3D%22.8%22%2F%3E%3C%2Fg%3E%3Ccircle%20cx%3D%22152%22%20cy%3D%22124%22%20r%3D%224.5%22%20fill%3D%22%23a49892%22%20stroke%3D%22%23463730%22%20stroke-width%3D%221.5%22%2F%3E%3C%2Fg%3E%3C%2Fsvg%3E', '[{"type":"p","text":"Dara Wibowo’s spare room has a rail along one wall, a steamer in the corner and a shelf of folded knits sorted by colour. She has sold secondhand clothes from here for six years. This is a profile of how she works, written from a visit and a long conversation."},{"type":"h2","text":"Finding the pieces"},{"type":"p","text":"Most of what she lists comes from family clear-outs and weekend markets. She buys slowly and says no often. If she would not wear it herself, or cannot say something true about it, it does not go on the rail."},{"type":"h2","text":"Writing an honest listing"},{"type":"p","text":"Flaws go in the first line, not the last. A small moth hole, a replaced zip or a faded armpit is photographed and described. She says it saves her time in the end, because the people who buy are the ones who wanted that piece anyway."},{"type":"quote","text":"If a buyer is surprised when the parcel opens, I have written the listing badly."},{"type":"p","text":"She submits her pieces to RE:WEAR for curator review before they go live, and treats the notes she gets back as free coaching. Her most common fix, she admits, is better light."}]'::jsonb, '2026-08-12'::date),
